// Authenticate JWT token
const token = $input.item.json.headers.authorization?.replace('Bearer ', '');

if (!token) {
  return {
    json: { error: 'Authentication required' },
    statusCode: 401
  };
}

// Verify JWT (simplified - use proper JWT library in production)
const jwt = require('jsonwebtoken');
const JWT_SECRET = process.env.JWT_SECRET;

try {
  const decoded = jwt.verify(token, JWT_SECRET);
  return {
    json: {
      user: decoded,
      request: $input.item.json.body
    }
  };
} catch (error) {
  return {
    json: { error: 'Invalid token' },
    statusCode: 401
  };
}

// Parse and validate request
const request = $input.item.json.request;
const user = $input.item.json.user;

// Validate required fields
if (!request.request) {
  return {
    json: { error: 'Missing required field: request' },
    statusCode: 400
  };
}

// Check permissions
if (user.role === 'free') {
  return {
    json: { error: 'Agent swarm requires Pro or Admin tier' },
    statusCode: 403
  };
}

// Generate task ID
const crypto = require('crypto');
const taskId = 'task_' + crypto.randomBytes(8).toString('hex');

// Determine which agents to use
const requestText = request.request.toLowerCase();
const selectedAgents = [];

if (requestText.includes('design') || requestText.includes('ui') || requestText.includes('frontend')) {
  selectedAgents.push('frontend');
}

if (requestText.includes('mcp') || requestText.includes('data') || requestText.includes('integration')) {
  selectedAgents.push('mcp-builder');
}

if (requestText.includes('seo') || requestText.includes('search') || requestText.includes('keywords')) {
  selectedAgents.push('seo');
}

if (requestText.includes('content') || requestText.includes('write') || requestText.includes('copy')) {
  selectedAgents.push('content');
}

if (requestText.includes('code review') || requestText.includes('security') || requestText.includes('audit')) {
  selectedAgents.push('code-review');
}

// Default to content agent if no match
if (selectedAgents.length === 0) {
  selectedAgents.push('content');
}

return {
  json: {
    taskId,
    request: request.request,
    industry: request.industry || 'general',
    priority: request.priority || 'medium',
    agents: selectedAgents,
    user: user,
    timestamp: new Date().toISOString()
  }
};

// Store task in database
const task = $input.item.json;

const db = require('pg');
const pool = new db.Pool({
  host: process.env.DB_HOST,
  port: process.env.DB_PORT,
  database: process.env.DB_DATABASE,
  user: process.env.DB_USER,
  password: process.env.DB_PASSWORD
});

await pool.query(
  'INSERT INTO agent_tasks (id, user_id, request, industry, priority, agents, status, created_at) VALUES ($1, $2, $3, $4, $5, $6, $7, $8)',
  [task.taskId, task.user.userId, task.request, task.industry, task.priority, JSON.stringify(task.agents), 'processing', task.timestamp]
);

return { json: task };

// Split into multiple agent tasks
const task = $input.item.json;
const agentTasks = [];

for (const agent of task.agents) {
  agentTasks.push({
    taskId: task.taskId,
    agent: agent,
    request: task.request,
    industry: task.industry,
    priority: task.priority,
    status: 'queued'
  });
}

return agentTasks.map(t => ({ json: t }));

// Aggregate all agent responses
const responses = $input.all();
const taskId = responses[0].json.taskId;

// Combine results
const aggregatedResults = {
  taskId: taskId,
  status: 'completed',
  results: responses.map(r => ({
    agent: r.json.agent,
    output: r.json.output
  })),
  completedAt: new Date().toISOString()
};

// Update task status in database
const db = require('pg');
const pool = new db.Pool({
  host: process.env.DB_HOST,
  port: process.env.DB_PORT,
  database: process.env.DB_DATABASE,
  user: process.env.DB_USER,
  password: process.env.DB_PASSWORD
});

await pool.query(
  'UPDATE agent_tasks SET status = $1, results = $2, completed_at = $3 WHERE id = $4',
  ['completed', JSON.stringify(aggregatedResults.results), aggregatedResults.completedAt, taskId]
);

return { json: aggregatedResults };
